// #8a2399 (6a993d7271c8db743d8a2399) F-17 AC4 «המשך בפועל וסיבת הסיום מוצגים בדוח» — реджект rej_bcc5d5c0 (21.10):
// в шапке отчёта поле «סיבת סיום» сразу после «משך». Факт проверки 04.11: отчёт QA-C2-2110-D2 (predefined_condition, 2:17),
// 1440 — «משך 2:17 דק׳», рядом «סיבת סיום: התקיים תנאי סיום שהוגדר בתרחיש» (скрин screenshots/2026-11-04/8a2399-report-predefined_condition-desktop.png).
// Роль business (testim), готовый отчёт, новых звонков нет. Только чтение → @prod-safe. Экран бизнеса — только десктоп.
import { Locator } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openReport } from './support';

const TAG = '#8a2399 · #6a993d7271c8db743d8a2399';
const CANDIDATE = 'QA-C2-2110-D2';

async function box(l: Locator, what: string) {
  await expect(l, what).toBeVisible();
  const b = await l.boundingBox();
  expect(b, `${what}: нет размеров`).not.toBeNull();
  return { left: b!.x, right: b!.x + b!.width, top: b!.y, bottom: b!.y + b!.height };
}

test.describe(`Отчёт — «סיבת סיום» рядом с «משך» в шапке (${TAG})`, () => {
  test(`${CANDIDATE} (predefined_condition): «משך 2:17 דק׳», сразу за ним «סיבת סיום: התקיים תנאי סיום שהוגדר בתרחיש» в той же строке @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.setViewportSize({ width: 1440, height: 900 });
    await openReport(page, CANDIDATE);

    // Источник: AC4 «המשך בפועל וסיבת הסיום מוצגים בדוח»; реджект 21.10 — причина раннего окончания в отчёте.
    const durLabel = page.getByText('משך', { exact: true }).first();
    const reasonLabel = page.getByText('סיבת סיום', { exact: true }).first();
    const durValue = page.getByText(/^2:17 דק/).first();
    const reasonValue = page.getByText('התקיים תנאי סיום שהוגדר בתרחיש', { exact: true }).first();

    const d = await box(durLabel, 'метка «משך»');
    const r = await box(reasonLabel, 'метка «סיבת סיום»');
    const dv = await box(durValue, 'значение «2:17 דק׳»');
    const rv = await box(reasonValue, 'значение причины');

    // Та же строка шапки (метки на одной высоте), RTL: «סיבת סיום» — слева от «משך».
    expect(Math.abs(r.top - d.top), 'метки «משך» и «סיבת סיום» в разных строках').toBeLessThanOrEqual(4);
    expect(r.right, '«סיבת סיום» должна идти после «משך» (левее в RTL)').toBeLessThanOrEqual(d.left + 1);
    // Значения под своими метками.
    expect(dv.top).toBeGreaterThanOrEqual(d.bottom - 2);
    expect(rv.top).toBeGreaterThanOrEqual(r.bottom - 2);
    expect(Math.abs(rv.top - dv.top), 'значения «משך» и причины в разных строках').toBeLessThanOrEqual(4);

    // «Сразу после»: между «משך» и «סיבת סיום» нет других полей шапки (תאריך — правее משך, שפה/מצב טכני — левее причины).
    const date = await box(page.getByText('תאריך', { exact: true }).first(), 'метка «תאריך»');
    const lang = await box(page.getByText('שפה', { exact: true }).first(), 'метка «שפה»');
    expect(date.left, '«תאריך» должна быть перед «משך»').toBeGreaterThanOrEqual(d.right - 1);
    if (Math.abs(lang.top - r.top) <= 4) {
      expect(lang.right, '«שפה» оказалась между «משך» и «סיבת סיום»').toBeLessThanOrEqual(r.left + 1);
    }
  });
});
